'use strict';
const crypto=require('node:crypto');
const assert=require('node:assert/strict');
const sha=b=>crypto.createHash('sha256').update(b).digest('hex');
const hex=s=>typeof s==='string'&&/^[a-f0-9]{64}$/.test(s);
const key=p=>{const k=crypto.createPublicKey(p);assert.equal(k.asymmetricKeyType,'ed25519');return k;};
const fingerprint=p=>sha(key(p).export({type:'spki',format:'der'}));
const payload=e=>Buffer.from(JSON.stringify(['PHOTON16:custody:v1',e.sequence,e.previous,e.action,e.id,e.ancestry,e.publicKey,e.custodyDigest]));
const verify=(p,e,s)=>typeof s==='string'&&crypto.verify(null,payload(e),key(p),Buffer.from(s,'base64'));
const head=e=>sha(Buffer.from(JSON.stringify([payload(e).toString('base64'),e.custodianSignature,e.possessionSignature,e.previousSignature||null])));
function replay(events,externalCustodian,producerRoots,expectedHead,transitions=[]){
 // A separately authenticated custodian and checkpoint must be supplied by the caller.
 assert.ok(externalCustodian&&hex(expectedHead),'missing external custody anchor');
 assert.ok(!producerRoots.includes(externalCustodian.ancestry),'producer custodian');
 const entries=new Map(),usedRoots=new Set(),usedKeys=new Set([fingerprint(externalCustodian.publicKey)]);
 let previous='0'.repeat(64),current=externalCustodian.publicKey,transitionIndex=0;
 const transitionPayload=t=>Buffer.from(JSON.stringify(['PHOTON16:custodian-transition:v1',t.ancestry,t.sequence,t.head,t.oldKey,t.newKey]));
 function rotate(sequence){while(transitionIndex<transitions.length&&transitions[transitionIndex].sequence===sequence){const t=transitions[transitionIndex++];assert.equal(t.ancestry,externalCustodian.ancestry);assert.equal(t.head,previous);assert.equal(t.oldKey,current);const fp=fingerprint(t.newKey);assert.ok(!usedKeys.has(fp),'reused custodian key');for(const [p,s] of [[current,t.oldSignature],[t.newKey,t.newSignature]])assert.ok(crypto.verify(null,transitionPayload(t),key(p),Buffer.from(s,'base64')),'custodian transition signature');usedKeys.add(fp);current=t.newKey;}}

 for(let i=0;i<events.length;i++){
  rotate(i);
  const e=events[i];assert.equal(e.sequence,i+1);assert.equal(e.previous,previous);assert.ok(hex(e.custodyDigest));assert.ok(typeof e.id==='string'&&e.id.length&&typeof e.ancestry==='string'&&e.ancestry.length);
  assert.ok(e.ancestry!==externalCustodian.ancestry&&!producerRoots.includes(e.ancestry));assert.ok(verify(current,e,e.custodianSignature),'custodian signature');
  const old=entries.get(e.id);
  if(e.action==='ENROLL'){
   assert.ok(!old&&!usedRoots.has(e.ancestry),'duplicate identity or root');
   const fp=fingerprint(e.publicKey);assert.ok(!usedKeys.has(fp),'duplicate key');assert.ok(verify(e.publicKey,e,e.possessionSignature),'possession');
   usedRoots.add(e.ancestry);usedKeys.add(fp);entries.set(e.id,{id:e.id,ancestry:e.ancestry,publicKey:e.publicKey,active:true});
  }else if(e.action==='ROTATE'){
   assert.ok(old&&old.active&&old.ancestry===e.ancestry);const fp=fingerprint(e.publicKey);assert.ok(!usedKeys.has(fp),'reused key');assert.ok(verify(old.publicKey,e,e.previousSignature),'old key');assert.ok(verify(e.publicKey,e,e.possessionSignature),'new key');usedKeys.add(fp);entries.set(e.id,{...old,publicKey:e.publicKey});
  }else if(e.action==='REVOKE'){
   assert.ok(old&&old.active&&old.ancestry===e.ancestry&&old.publicKey===e.publicKey);entries.set(e.id,{...old,active:false});
  }else throw Error('unknown action');
  previous=head(e);
 }
 rotate(events.length);assert.equal(transitionIndex,transitions.length,'unconsumed transition');
 assert.equal(previous,expectedHead,'external checkpoint mismatch');
 return {registry:[...entries.values()].filter(e=>e.active),head:previous,currentCustodianKey:current,events:events.length,custody:'SIGNATURES_VALID',independence:'UNVERIFIED',releaseAuthority:'HOLD'};
}
module.exports={replay,payload,head};

'use strict';
const crypto=require('node:crypto'),assert=require('node:assert/strict');
const custody=require('./custody-registry.cjs'),temporal=require('./temporal-witness.cjs');
const {fingerprint}=require('./checkpoint-freshness.cjs');
const sha=b=>crypto.createHash('sha256').update(b).digest('hex');
const hex=x=>typeof x==='string'&&/^[0-9a-f]{64}$/.test(x);
const transitionPayload=t=>Buffer.from(JSON.stringify(['PHOTON16:custodian-transition:v1',t.ancestry,t.sequence,t.head,t.oldKey,t.newKey]));
const transitionHead=ts=>ts.reduce((h,t)=>sha(Buffer.from(JSON.stringify([h,transitionPayload(t).toString('base64'),t.oldSignature,t.newSignature]))),'0'.repeat(64));
const receiptPayload=r=>Buffer.from(JSON.stringify(['PHOTON16:checkpoint:v2',r.registryId,r.sequence,r.head,r.transitionCount,r.transitionHead,r.previousSequence,r.previousHead,r.previousTransitionCount,r.previousTransitionHead,r.challenge,r.custodianFingerprint]));
function advance(events,transitions,retained,receipt,trust,challenge){
 assert.ok(retained&&trust&&hex(challenge)&&hex(retained.head)&&hex(retained.transitionHead));
 assert.equal(retained.registryId,trust.registryId);assert.equal(receipt.registryId,trust.registryId);
 for(const n of [retained.sequence,retained.transitionCount,receipt.sequence,receipt.transitionCount])assert.ok(Number.isSafeInteger(n)&&n>=0);
 assert.ok(receipt.sequence>=retained.sequence&&receipt.transitionCount>=retained.transitionCount,'rollback');
 assert.equal(receipt.previousSequence,retained.sequence);assert.equal(receipt.previousHead,retained.head);
 assert.equal(receipt.previousTransitionCount,retained.transitionCount);assert.equal(receipt.previousTransitionHead,retained.transitionHead);
 assert.equal(receipt.challenge,challenge);assert.equal(events.length,receipt.sequence);assert.equal(transitions.length,receipt.transitionCount);
 assert.equal(retained.sequence?custody.head(events[retained.sequence-1]):'0'.repeat(64),retained.head);
 assert.equal(transitionHead(transitions.slice(0,retained.transitionCount)),retained.transitionHead);
 assert.equal(transitionHead(transitions),receipt.transitionHead);
 assert.ok(transitions.slice(retained.transitionCount).every(t=>t.sequence>=retained.sequence),'retroactive transition');
 assert.ok(transitions.slice(0,retained.transitionCount).every(t=>t.sequence<=retained.sequence),'invalid retained transition');
 const state=custody.replay(events,trust.custodian,trust.producerRoots,receipt.head,transitions);
 assert.equal(receipt.custodianFingerprint,fingerprint(state.currentCustodianKey));
 assert.ok(crypto.verify(null,receiptPayload(receipt),crypto.createPublicKey(state.currentCustodianKey),Buffer.from(receipt.signature,'base64')),'current custodian receipt signature');
 return {registryId:trust.registryId,sequence:state.events,head:state.head,transitionCount:transitions.length,transitionHead:receipt.transitionHead,custodianFingerprint:receipt.custodianFingerprint,status:'LOGICAL_CHECKPOINT_VALID',releaseAuthority:'HOLD',wallClock:'UNVERIFIED'};
}
function qualifyCurrent(candidate,records,events,transitions,retained,receipt,trust,challenge){
 try{const next=advance(events,transitions,retained,receipt,trust,challenge);return {...temporal.qualify(candidate,records,events,{custodian:trust.custodian,producerRoots:trust.producerRoots,sequence:next.sequence,head:next.head,transitions}),checkpoint:next};}catch{return {status:'HOLD',reason:'CHECKPOINT_REJECTED',releaseAuthority:'HOLD',authenticated:0};}
}
module.exports={advance,qualifyCurrent,transitionPayload,transitionHead,receiptPayload};

'use strict';
const crypto=require('node:crypto');
const custody=require('./custody-registry.cjs');
const transition=require('./custodian-transition.cjs');
const sha=x=>crypto.createHash('sha256').update(x).digest('hex');
const zero='0'.repeat(64);
function compare(a,b,retained,trust,challengeA,challengeB){
 const verify=(x,c)=>{try{return transition.advance(x.events,x.transitions,retained,x.receipt,trust,c);}catch{return null;}};
 const A=verify(a,challengeA),B=verify(b,challengeB);
 const base={releaseAuthority:'HOLD',independentWitness:'UNVERIFIED',selected:null};
 if(!A||!B)return {...base,status:'INVALID_BRANCH',valid:[!!A,!!B]};
 const prefix=(x,y)=>{
  if(x.events.length>y.events.length||x.transitions.length>y.transitions.length)return false;
  if((x.events.length?custody.head(y.events[x.events.length-1]):zero)!==(x.events.length?custody.head(x.events.at(-1)):zero))return false;
  if(transition.transitionHead(y.transitions.slice(0,x.transitions.length))!==transition.transitionHead(x.transitions))return false;
  // A newly appended rotation cannot change the signing authority of an already observed event.
  return y.transitions.slice(x.transitions.length).every(t=>t.sequence>=x.events.length);
 };
 const ab=prefix(a,b),ba=prefix(b,a);
 if(ab&&ba)return {...base,status:'IDENTICAL_HISTORY',heads:[A,B]};
 if(ab||ba)return {...base,status:'COMPATIBLE_EXTENSION',direction:ab?'A_TO_B':'B_TO_A',heads:[A,B]};
 const evidence=[{checkpoint:A,branch:a},{checkpoint:B,branch:b}].map(x=>({digest:sha(JSON.stringify(x)),...x})).sort((x,y)=>x.digest.localeCompare(y.digest));
 return {...base,status:'AUTHENTICATED_FORK',evidence,conflictDigest:sha(JSON.stringify(evidence.map(x=>x.digest)))};
}
module.exports={compare};

'use strict';
const crypto=require('node:crypto');
const {replay}=require('./custody-registry.cjs');
const hex=(s,n)=>typeof s==='string'&&new RegExp('^[a-f0-9]{'+n+'}$').test(s);
const payload=r=>Buffer.from(JSON.stringify(['PHOTON16:temporal-witness:v2',r.sourceCommit,r.wasmSha256,r.manifestSha256,r.registryHead,r.registrySequence,r.witnessId,r.ancestry,r.observation]));
function qualify(candidate,records,events,anchor){
 const hold=reason=>({status:'HOLD',reason,authenticated:0,releaseAuthority:'HOLD'});
 // Anchor must be obtained independently, never extracted from candidate or records.
 if(!anchor||!hex(anchor.head,64)||!Number.isSafeInteger(anchor.sequence)||anchor.sequence<0||!Array.isArray(anchor.producerRoots)||!anchor.producerRoots.length)return hold('MISSING_EXTERNAL_ANCHOR');
 if(!candidate||candidate.status!=='STAGED_BUNDLE_PASS'||!hex(candidate.sourceCommit,40)||!hex(candidate.wasmSha256,64)||!hex(candidate.manifestSha256,64))return hold('INVALID_CANDIDATE');
 let state;
 try{state=replay(events,anchor.custodian,anchor.producerRoots,anchor.head,anchor.transitions||[]);if(state.events!==anchor.sequence)return hold('SEQUENCE_MISMATCH');}catch{return hold('CUSTODY_REPLAY_REJECTED');}
 if(!Array.isArray(records)||records.length!==3)return hold('THREE_ROOTS_REQUIRED');
 const seen=new Set(),roots=new Set(),keys=new Set();
 for(const r of records){
  if(!r||r.registryHead!==state.head||r.registrySequence!==state.events)return hold('STALE_REGISTRY');
  if(!['sourceCommit','wasmSha256','manifestSha256'].every(k=>r[k]===candidate[k])||r.observation!=='REPRODUCED_AND_EXECUTED')return hold('OBSERVATION_MISMATCH');
  const entry=state.registry.find(x=>x.id===r.witnessId);
  if(!entry||entry.ancestry!==r.ancestry)return hold('INACTIVE_OR_UNKNOWN_WITNESS');
  if(seen.has(entry.id)||roots.has(entry.ancestry))return hold('DUPLICATE_ROOT');
  try{const k=crypto.createPublicKey(entry.publicKey);const fp=k.export({type:'spki',format:'der'}).toString('hex');if(keys.has(fp)||k.asymmetricKeyType!=='ed25519'||typeof r.signature!=='string'||!crypto.verify(null,payload(r),k,Buffer.from(r.signature,'base64')))return hold('SIGNATURE_REJECTED');keys.add(fp);}catch{return hold('SIGNATURE_REJECTED');}
  seen.add(entry.id);roots.add(entry.ancestry);
 }
 return {status:'CURRENT_SIGNATURES_VALID',authenticated:3,registryHead:state.head,registrySequence:state.events,independence:'UNVERIFIED',releaseAuthority:'HOLD'};
}
module.exports={qualify,payload};

