'use strict';
const crypto=require('node:crypto');
const custody=require('./custody-registry.cjs');
const transitions=require('./custodian-transition.cjs');
const sha=x=>crypto.createHash('sha256').update(x).digest('hex');
const hex=x=>typeof x==='string'&&/^[0-9a-f]{64}$/.test(x);
const fingerprint=p=>{const k=crypto.createPublicKey(p);if(k.asymmetricKeyType!=='ed25519')throw Error('wrong key type');return sha(k.export({type:'spki',format:'der'}));};
const payload=r=>Buffer.from(JSON.stringify(['PHOTON16:independent-custody:v1',r.registryId,r.registryHead,r.registrySequence,r.transitionHead,r.transitionCount,r.witnessId,r.ancestry,r.keyFingerprint,r.custodyDigest,r.auditorId,r.controlRoots,r.challenge]));
function qualify(events,rotations,retained,receipt,trust,challenge,observations,auditors,producerControlRoots){
 const hold=reason=>({status:'HOLD',reason,authenticated:0,independence:'UNVERIFIED',releaseAuthority:'HOLD'});
 try{
  // The trust configuration, auditor registry and control-root inventory are external inputs, not candidate fields.
  if(!Array.isArray(auditors)||auditors.length===0||!Array.isArray(producerControlRoots)||producerControlRoots.length===0)return hold('MISSING_EXTERNAL_CONTROL_ANCHOR');
  const checkpoint=transitions.advance(events,rotations,retained,receipt,trust,challenge);
  const state=custody.replay(events,trust.custodian,trust.producerRoots,checkpoint.head,rotations);
  if(!Array.isArray(observations)||observations.length!==3)return hold('THREE_OBSERVATIONS_REQUIRED');
  const roots=new Set(producerControlRoots),witnessIds=new Set(),witnessRoots=new Set(),auditorIds=new Set(),auditorKeys=new Set(),witnessKeys=new Set(state.registry.map(e=>fingerprint(e.publicKey)));
  const forbiddenKeys=new Set([fingerprint(trust.custodian.publicKey),...rotations.map(r=>fingerprint(r.newKey)),...witnessKeys]);
  for(const r of observations){
   if(!r||r.registryId!==checkpoint.registryId||r.registryHead!==checkpoint.head||r.registrySequence!==checkpoint.sequence||r.transitionHead!==checkpoint.transitionHead||r.transitionCount!==checkpoint.transitionCount||r.challenge!==challenge)return hold('STALE_OBSERVATION');
   const entry=state.registry.find(e=>e.id===r.witnessId),auditor=auditors.find(e=>e.id===r.auditorId);
   if(!entry||entry.ancestry!==r.ancestry||fingerprint(entry.publicKey)!==r.keyFingerprint||witnessIds.has(entry.id)||witnessRoots.has(entry.ancestry))return hold('WITNESS_IDENTITY_REJECTED');
   const last=events.filter(e=>e.id===entry.id).at(-1);
   if(!hex(r.custodyDigest)||!last||last.custodyDigest!==r.custodyDigest)return hold('CUSTODY_DIGEST_MISMATCH');
   if(!auditor||auditorIds.has(auditor.id)||!Array.isArray(auditor.controlRoots)||!auditor.controlRoots.length)return hold('AUDITOR_IDENTITY_REJECTED');
   const fp=fingerprint(auditor.publicKey);
   if(forbiddenKeys.has(fp)||auditorKeys.has(fp))return hold('AUDITOR_KEY_COLLISION');
   if(!Array.isArray(r.controlRoots)||!r.controlRoots.length||r.controlRoots.some(x=>typeof x!=='string'||!x.length)||new Set(r.controlRoots).size!==r.controlRoots.length)return hold('CONTROL_ROOTS_MISSING');
   const group=new Set([...r.controlRoots,...auditor.controlRoots]);
   for(const root of group)if(roots.has(root))return hold('SHARED_CONTROL_ROOT');
   if(!crypto.verify(null,payload(r),crypto.createPublicKey(auditor.publicKey),Buffer.from(r.signature,'base64')))return hold('ATTESTATION_SIGNATURE_REJECTED');
   for(const root of group)roots.add(root);
   witnessIds.add(entry.id);witnessRoots.add(entry.ancestry);auditorIds.add(auditor.id);auditorKeys.add(fp);
  }
  return {status:'DECLARED_ANCESTRY_DISJOINT',authenticated:3,checkpoint,independence:'UNVERIFIED',releaseAuthority:'HOLD'};
 }catch{return hold('CUSTODY_QUALIFICATION_REJECTED');}
}
module.exports={qualify,payload,fingerprint};

'use strict';
const crypto=require('node:crypto');
const sha=b=>crypto.createHash('sha256').update(b).digest('hex');
const hex=(x,n=64)=>typeof x==='string'&&new RegExp('^[a-f0-9]{'+n+'}$').test(x);
const bytes=x=>Buffer.from(JSON.stringify(x));
const context=c=>[c.sourceCommit,c.wasmSha256,c.manifestSha256,c.registryHead,c.registrySequence,c.transitionHead,c.transitionCount,c.challenge];
const commitment=(c,id,observation,salt)=>sha(bytes(['PHOTON16:blind-opening:v1',context(c),id,observation,salt]));
const sealPayload=(c,r)=>bytes(['PHOTON16:blind-seal:v1',context(c),r.id,r.commitment]);
const barrierPayload=(c,seals)=>bytes(['PHOTON16:blind-barrier:v1',context(c),seals.map(r=>[r.id,r.commitment,r.signature]).sort((a,b)=>a[0].localeCompare(b[0]))]);
const revealPayload=(c,r,barrierDigest)=>bytes(['PHOTON16:blind-reveal:v1',context(c),barrierDigest,r.id,r.observation,r.salt]);
function verify(key,p,s){try{const k=crypto.createPublicKey(key);return k.asymmetricKeyType==='ed25519'&&typeof s==='string'&&crypto.verify(null,p,k,Buffer.from(s,'base64'));}catch{return false;}}
function qualify(c,seals,barrier,reveals,registry,coordinator){
 const hold=reason=>({status:'HOLD',reason,releaseAuthority:'HOLD'});
 try{
  // Registry and coordinator must be supplied from independently retained custody.
  if(!c||!hex(c.sourceCommit,40)||![c.wasmSha256,c.manifestSha256,c.registryHead,c.transitionHead,c.challenge].every(x=>hex(x))||![c.registrySequence,c.transitionCount].every(x=>Number.isSafeInteger(x)&&x>=0))return hold('INVALID_CONTEXT');
  if(!Array.isArray(registry)||registry.length!==3||!coordinator)return hold('MISSING_TRUST');
  const ids=new Set(),roots=new Set(),keys=new Set();
  const fp=p=>{const k=crypto.createPublicKey(p);if(k.asymmetricKeyType!=='ed25519')throw Error('key type');return sha(k.export({type:'spki',format:'der'}));};
  const coordinatorKey=fp(coordinator.publicKey);
  for(const e of registry){const k=fp(e.publicKey);if(!e.id||!e.ancestry||ids.has(e.id)||roots.has(e.ancestry)||keys.has(k)||k===coordinatorKey||e.ancestry===coordinator.ancestry)return hold('SHARED_TRUST');ids.add(e.id);roots.add(e.ancestry);keys.add(k);}
  if(!Array.isArray(seals)||seals.length!==3||new Set(seals.map(r=>r.id)).size!==3)return hold('INCOMPLETE_SEALS');
  for(const r of seals){const e=registry.find(x=>x.id===r.id);if(!e||!hex(r.commitment)||!verify(e.publicKey,sealPayload(c,r),r.signature))return hold('INVALID_SEAL');}
  const bp=barrierPayload(c,seals),bd=sha(bp);
  if(!barrier||barrier.digest!==bd||!verify(coordinator.publicKey,bp,barrier.signature))return hold('INVALID_BARRIER');
  if(!Array.isArray(reveals)||reveals.length!==3||new Set(reveals.map(r=>r.id)).size!==3)return hold('INCOMPLETE_REVEALS');
  for(const r of reveals){const e=registry.find(x=>x.id===r.id),s=seals.find(x=>x.id===r.id);if(!e||!s||!hex(r.observation)||!hex(r.salt)||commitment(c,r.id,r.observation,r.salt)!==s.commitment||!verify(e.publicKey,revealPayload(c,r,bd),r.signature))return hold('INVALID_OPENING');}
  if(new Set(reveals.map(r=>r.salt)).size!==3)return hold('REUSED_SALT');
  const agreement=new Set(reveals.map(r=>r.observation)).size===1;
  return {status:agreement?'COMMITTED_AGREEMENT':'COMMITTED_DISAGREEMENT',barrierDigest:bd,observations:reveals.map(r=>({id:r.id,digest:r.observation})),blindAcquisition:'UNVERIFIED',independence:'UNVERIFIED',releaseAuthority:'HOLD'};
 }catch{return hold('INVALID_EVIDENCE');}
}
module.exports={qualify,commitment,sealPayload,barrierPayload,revealPayload};

'use strict';
const crypto=require('node:crypto'),blind=require('./blind-witness.cjs');
const sha=x=>crypto.createHash('sha256').update(x).digest('hex');
const hex=(x,n=64)=>typeof x==='string'&&new RegExp('^[a-f0-9]{'+n+'}$').test(x);
const fields=['abi','codons','stages','updates','returns','conservation','traceSha256'];
const semantic=r=>sha(JSON.stringify(['PHOTON16:semantic:v1',...fields.map(k=>r[k])]));
const digest=r=>sha(JSON.stringify(['PHOTON16:reproduction:v1',r.sourceCommit,r.wasmSha256,r.toolchainSha256,r.executionLogSha256,semantic(r)]));
function valid(r){return r&&hex(r.sourceCommit,40)&&[r.wasmSha256,r.toolchainSha256,r.executionLogSha256,r.traceSha256].every(x=>hex(x))&&['abi','codons','stages','updates','returns'].every(k=>Number.isSafeInteger(r[k])&&r[k]>=0)&&typeof r.conservation==='boolean';}
function compare(c,seals,barrier,reveals,registry,coordinator,reports,reference){
 const hold=reason=>({status:'HOLD',reason,releaseAuthority:'HOLD'});
 try{
  const transcript=blind.qualify(c,seals,barrier,reveals,registry,coordinator);
  if(transcript.status==='HOLD')return hold(transcript.reason);
  if(!valid(reference)||reference.sourceCommit!==c.sourceCommit||reference.wasmSha256!==c.wasmSha256||reference.abi!==83||reference.codons!==552960||reference.stages!==4423680||reference.updates!==161280||reference.returns!==2880||reference.conservation!==true)return hold('INVALID_REFERENCE');
  if(!Array.isArray(reports)||reports.length!==3||new Set(reports.map(r=>r.id)).size!==3)return hold('INCOMPLETE_REPORTS');
  const rows=[];
